from __future__ import annotations

import base64
import json
import os
from dataclasses import dataclass, asdict
from typing import Any, Dict, Iterable, List, Optional, Union

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


@dataclass
class FieldResult:
    value: Any
    confidence: float


@dataclass
class ValidationResult:
    valid: bool
    missing_required_fields: List[str]
    low_confidence_fields: List[str]
    fields: Dict[str, FieldResult]


class StructuredDocumentExtractionError(Exception):
    pass


def _read_document_bytes(document: Union[str, bytes, bytearray]) -> bytes:
    if isinstance(document, (bytes, bytearray)):
        return bytes(document)
    if not isinstance(document, str):
        raise TypeError("document must be bytes, bytearray, or file path string")
    with open(document, "rb") as f:
        return f.read()


def _to_confidence(value: Any) -> float:
    try:
        conf = float(value)
    except (TypeError, ValueError):
        return 0.0
    if conf < 0:
        return 0.0
    if conf > 1:
        return 1.0
    return conf


def _extract_field_value(field: Any) -> Any:
    if field is None:
        return None
    if isinstance(field, dict):
        if "value" in field:
            return field["value"]
        if "content" in field:
            return field["content"]
        if "text" in field:
            return field["text"]
        return field
    for attr in ("value", "content", "text"):
        if hasattr(field, attr):
            return getattr(field, attr)
    return field


def _extract_field_confidence(field: Any) -> float:
    if field is None:
        return 0.0
    if isinstance(field, dict):
        for key in ("confidence", "probability", "score"):
            if key in field:
                return _to_confidence(field[key])
        return 0.0
    for attr in ("confidence", "probability", "score"):
        if hasattr(field, attr):
            return _to_confidence(getattr(field, attr))
    return 0.0


def _get_fields_from_analyze_result(result: Any) -> Dict[str, Any]:
    documents = getattr(result, "documents", None)
    if documents:
        first_doc = documents[0]
        fields = getattr(first_doc, "fields", None)
        if fields:
            return fields
        if isinstance(first_doc, dict):
            return first_doc.get("fields", {}) or {}
    if isinstance(result, dict):
        if result.get("documents"):
            first_doc = result["documents"][0]
            return first_doc.get("fields", {}) or {}
        if result.get("fields"):
            return result["fields"]
    return {}


def validate_and_extract_invoice(
    document: Union[str, bytes, bytearray],
    required_fields: Iterable[str],
    min_confidence: float = 0.8,
    *,
    endpoint: Optional[str] = None,
    key: Optional[str] = None,
    model_id: str = "prebuilt-invoice",
) -> ValidationResult:
    endpoint = endpoint or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = key or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise StructuredDocumentExtractionError(
            "Missing Azure Document Intelligence credentials. "
            "Set AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY."
        )

    doc_bytes = _read_document_bytes(document)

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    poller = client.begin_analyze_document(
        model_id=model_id,
        body=doc_bytes,
        content_type="application/octet-stream",
    )
    result = poller.result()

    raw_fields = _get_fields_from_analyze_result(result)

    normalized_fields: Dict[str, FieldResult] = {}
    missing_required_fields: List[str] = []
    low_confidence_fields: List[str] = []

    for field_name in required_fields:
        field = raw_fields.get(field_name) if raw_fields else None
        value = _extract_field_value(field)
        confidence = _extract_field_confidence(field)
        normalized_fields[field_name] = FieldResult(value=value, confidence=confidence)

        if value is None or value == "":
            missing_required_fields.append(field_name)
        elif confidence < min_confidence:
            low_confidence_fields.append(field_name)

    valid = not missing_required_fields and not low_confidence_fields

    return ValidationResult(
        valid=valid,
        missing_required_fields=missing_required_fields,
        low_confidence_fields=low_confidence_fields,
        fields=normalized_fields,
    )


def validate_and_extract_invoice_json(
    document: Union[str, bytes, bytearray],
    required_fields: Iterable[str],
    min_confidence: float = 0.8,
    *,
    endpoint: Optional[str] = None,
    key: Optional[str] = None,
    model_id: str = "prebuilt-invoice",
) -> Dict[str, Any]:
    result = validate_and_extract_invoice(
        document=document,
        required_fields=required_fields,
        min_confidence=min_confidence,
        endpoint=endpoint,
        key=key,
        model_id=model_id,
    )
    return {
        "valid": result.valid,
        "missing_required_fields": result.missing_required_fields,
        "low_confidence_fields": result.low_confidence_fields,
        "fields": {name: asdict(field) for name, field in result.fields.items()},
    }
